using System;using System.IO;using System.Linq;using System.Collections.Generic;using V15Voice;
public sealed class AnchorFake:KokoroEngine {public double Seconds=10.6;public List<string> Texts=new List<string>();public override void CheckFiles(){}public override Wave Generate(string text,double speed,string path){Texts.Add(text);return Signal(Seconds);}public static Wave Signal(double seconds){int n=(int)Math.Round(seconds*24000);var data=new short[n];for(int i=0;i<n;i++){double env=Math.Min(1,Math.Min(i/120.0,(n-1-i)/120.0));data[i]=(short)(6000*env*Math.Sin(i*2*Math.PI*220/24000));}return new Wave{Rate=24000,Samples=data};}}
public static class AnchoredTests {
 static int count;static string root,work;
 static void Check(bool yes,string name){if(!yes)throw new Exception("FAIL "+name);Console.WriteLine("PASS "+name);count++;}
 static List<Cue> Cues(){return new List<Cue>{new Cue{Id=1,Start=0,End=2,Text="This is a longer sentence"},new Cue{Id=2,Start=2.1,End=5,Text="that continues across display cues"},new Cue{Id=3,Start=5.1,End=10,Text="and finishes naturally without fixed word limits."}};}
 static RenderOptions Options(){return new RenderOptions{Anchored=true,Locked=false,GentleFit=true,MinSpeed=.9,MaxSpeed=1.3,Breathing=BreathMode.None};}
 static string Render(string name,AnchorFake engine,RenderOptions options,List<Cue> cues=null){return Renderer.Render(cues??Cues(),engine,options,Path.Combine(work,name+".wav"),(p,m)=>{});}
 static bool Failed(Action action,string includes){try{action();return false;}catch(Exception e){return !(e is OperationCanceledException)&&e.Message.Contains(includes);}}
 static double Pitch(Wave w){int crossings=0;int a=2400,b=w.Samples.Length-2400;for(int i=a+1;i<b;i++)if(w.Samples[i-1]<0&&w.Samples[i]>=0)crossings++;return crossings/((b-a)/24000.0);}
 public static void Main(string[] args){root=AppDomain.CurrentDomain.BaseDirectory;work=Path.Combine(Path.GetTempPath(),"v1411-tests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(work);Console.WriteLine("Artifacts "+work);
  var cues=Cues();string original=Scripts.ToSrt(cues);Check(AnchoredVoice.Plan(cues).Count==1,"Display cues are grouped into a meaningful stage");var o=Options();var e=new AnchorFake{Root=root};string wav=Render("fast",e,o,cues);Check(e.Texts.Count==1&&e.Texts[0]==String.Join(" ",cues.Select(c=>c.Text)),"One continuous speech request rather than one request per display cue");Check(FinalAudio.PcmFrames(wav)==240000&&o.AnchorResult.Complete,"Fast speech fitted and remeasured to exactly source duration");Check(o.AnchorResult.Stages[0].Fit.Speed>=1&&o.AnchorResult.Stages[0].Fit.Speed<=1.1,"Automatic speedup respects gentle bounds");Check(Scripts.ToSrt(cues)==original,"Source words and timecodes remain unchanged");
  o=Options();e=new AnchorFake{Root=root,Seconds=9.4};wav=Render("slow",e,o);Check(o.AnchorResult.Stages[0].Fit.Success&&o.AnchorResult.Stages[0].Fit.Speed>=.9&&o.AnchorResult.Stages[0].Fit.Speed<1,"Slowdown is automatic without SlowShort checkbox");Check(Math.Abs(Pitch(Wave.Read(wav))-220)<4,"Tempo changes retain sine pitch");
  foreach(double duration in new[]{8.0,14.0}){o=Options();e=new AnchorFake{Root=root,Seconds=duration};string path=Path.Combine(work,"reject"+duration+".wav");File.WriteAllText(path,"KEEP");Check(Failed(()=>Renderer.Render(Cues(),e,o,path,(p,m)=>{}),"cue 1–3"),"Out-of-bounds stage reports exact source cue IDs "+duration);Check(!o.AnchorResult.Complete&&File.ReadAllText(path)=="KEEP"&&!Directory.GetFiles(work,"reject"+duration+" (*).wav").Any(),"Invalid WAV not published, previous WAV preserved "+duration);}
  Check(!Directory.GetFiles(work,".v15*.tmp").Any(),"Failed renders remove temporary WAV");
  cues=Cues();cues[1].AnchorAfter=true;var plan=AnchoredVoice.Plan(cues);Check(plan.Count==2&&plan[0].End==5&&plan[1].Start==5.1,"Manual hard anchor ends stage at the selected source cue");o=Options();e=new AnchorFake{Root=root,Seconds=5.2};wav=Render("anchors",e,o,cues);Check(FinalAudio.PcmFrames(wav)==240000&&o.AnchorResult.Stages.All(r=>r.Fit.Success),"Both sides of hard anchor fit independently");var wave=Wave.Read(wav);Check(wave.Samples.Skip(120000).Take(2400).All(x=>x==0),"Explicit source silence between stages remains silent");
  cues=Cues();cues[1].Start=3;Check(AnchoredVoice.Plan(cues).Count==2,"Long explicit source gap is an automatic stage boundary");
  string longText=String.Join(" ",Enumerable.Repeat("Natural sentences retain their words, while longer clauses can be split safely.",18));Check(String.Join(" ",AnchoredVoice.SpeechUnits(longText)).Split(' ').SequenceEqual(longText.Split(' ')),"Long speech unit splitting preserves all words");Check(AnchoredVoice.SpeechUnits(Cues()[0].Text+" "+Cues()[1].Text+" "+Cues()[2].Text).Count==1,"No ten-word limit on natural speech units");
  for(int batch=0;batch<4;batch++)for(int timeline=0;timeline<3;timeline++){o=Options();AnchoredVoice.ConfigureBatch(o,true,batch,timeline);Check(o.Anchored==(batch==3||(batch==0&&timeline==2))&&!o.Prose&&(!o.Anchored||!o.Locked),"Timed batch routing "+batch+" timeline "+timeline);AnchoredVoice.ConfigureBatch(o,false,batch,timeline);Check(o.Prose&&!o.Anchored&&!o.Locked,"Plain TXT batch routing "+batch+" timeline "+timeline);}
  var settings=VoiceSettings.From(new VoiceSettings{Mode=2,BatchMode=3,AnchorSrt=true}.Xml());Check(settings.Mode==2&&settings.BatchMode==3&&settings.AnchorSrt,"New mode, batch mode and optional SRT persist");
  string input=Path.Combine(work,"source.srt");File.WriteAllText(input,original);var job=BatchJob.Load(input);job.Cues[1].AnchorAfter=true;job.TimelineReport="line 1\r\nline 2";job.Warning="review";string queue=Path.Combine(work,"queue.xml");QueueStore.Save(queue,new[]{job});var loaded=QueueStore.Load(queue).Single();Check(loaded.Cues[1].AnchorAfter&&loaded.TimelineReport==job.TimelineReport&&loaded.Warning=="review","Queue preserves manual anchors and reports");
  Directory.CreateDirectory(Path.Combine(work,"breaths"));AnchorFake.Signal(.2).Write(Path.Combine(work,"breaths","sample.wav"));var breathCues=new List<Cue>{new Cue{Start=0,End=9,Text="First sentence stays natural. Second sentence continues calmly. Third sentence ends here. Final sentence closes the story."}};o=Options();Render("no-breath",new AnchorFake{Root=work,Seconds=2},o,breathCues);double withoutBreath=o.AnchorResult.Stages[0].Fit.Natural;o=Options();o.Breathing=BreathMode.Auto;Render("auto-breath",new AnchorFake{Root=work,Seconds=2},o,breathCues);Check(o.AnchorResult.Stages[0].Fit.Natural>withoutBreath&&o.AnchorResult.Complete,"Auto breath is included before fitting stage duration");o=Options();o.Breathing=BreathMode.Custom;o.BreathPath=Path.Combine(work,"breaths","sample.wav");o.BreathEvery=1;Render("custom-breath",new AnchorFake{Root=work,Seconds=2},o,breathCues);Check(o.AnchorResult.Stages[0].Fit.Natural>withoutBreath&&FinalAudio.PcmFrames(o.AnchorResult.Wav)==216000,"Custom breath shares exact stage budget");
  o=Options();o.NormalizeLoudness=true;wav=Render("normalized",new AnchorFake{Root=root},o);Check(FinalAudio.PcmFrames(wav)==240000,"Loudness finishing retains exact timeline");
  o=Options();bool saw=false;o.AnchorAlignment=(audio,units)=>{saw=FinalAudio.PcmFrames(audio)==240000&&units.Count==1&&units[0].End<=10.001;return new SubtitleDocument{Duration=10,Cues=new List<SubtitleCue>{new SubtitleCue{Start=0,End=10,Text=String.Join(" ",Cues().Select(c=>c.Text))}}};};wav=Render("with-srt",new AnchorFake{Root=root},o);Check(saw&&File.Exists(o.AnchorResult.Srt),"Optional alignment receives actual fitted WAV; exports separate SRT");
  o=Options();o.AnchorAlignment=(audio,units)=>{throw new Exception("Missing alignment model");};wav=Render("no-model",new AnchorFake{Root=root},o);Check(File.Exists(wav)&&o.AnchorResult.NeedsReview&&o.AnchorResult.Srt=="","Optional SRT failure keeps valid WAV and reports review");
  o=Options();o.AnchorAlignment=(audio,units)=>new SubtitleDocument{Duration=10,Cues=new List<SubtitleCue>{new SubtitleCue{Start=0,End=10,Text="Wrong words."}}};wav=Render("wrong-srt",new AnchorFake{Root=root},o);Check(File.Exists(wav)&&o.AnchorResult.Srt==""&&o.AnchorResult.AlignmentNote.Length>0,"Changed words cannot be published as aligned SRT");
  o=Options();e=new AnchorFake{Root=root};string cancelPath=Path.Combine(work,"cancel.wav");File.WriteAllText(cancelPath,"KEEP");bool cancelled=false;try{Renderer.Render(Cues(),e,o,cancelPath,(p,m)=>{if(p==90)e.Cancel();});}catch(OperationCanceledException){cancelled=true;}Check(cancelled&&File.ReadAllText(cancelPath)=="KEEP"&&!Directory.GetFiles(work,".v15*.tmp").Any(),"Cancellation before publishing preserves old WAV and removes partial output");
  string input2=Path.Combine(work,"source2.srt");File.WriteAllText(input2,original);var jobs=new List<BatchJob>{BatchJob.Load(input),BatchJob.Load(input2)};jobs[0].Cues[1].AnchorAfter=true;BatchRunner.Run(jobs,false,()=>false,(j,path,notify)=>Renderer.Render(j.Cues,new AnchorFake{Root=root,Seconds=j==jobs[0]?14:10.6},Options(),path,notify),(p,m)=>{});Check(jobs[0].State==JobState.Failed&&jobs[1].State==JobState.Done&&jobs[0].Cues[1].AnchorAfter,"Batch continues after invalid file and retains anchors on rollback");
  int fits=0;foreach(double target in new[]{2.0,5.0,12.0})foreach(double ratio in new[]{.92,.98,1.03,1.08}){var fit=AnchoredVoice.Fit(AnchorFake.Signal(target*ratio),target,Options(),root,work,()=>false);if(!fit.Success)throw new Exception("Numerical fit "+target+" "+ratio+": "+fit.Reason);Check(fit.Audio.Samples.Length==(int)Math.Round(target*24000)&&Math.Abs(fit.SampleAdjustment)<=.020001,"Measured fit "+target+"s ratio "+ratio);fits++;}Check(fits==12,"Duration fitting exercised across short and longer stages");
  if(args.Length>0){string hash=StateFiles.Hash(args[0]);var originalVoice=Wave.Read(args[0]);var fit=AnchoredVoice.Fit(originalVoice,74.210,Options(),root,work,()=>false);Check(fit.Success&&fit.Audio.Samples.Length==1781040,"Real supplied voice fitted from "+originalVoice.Duration.ToString("0.000000")+" to 74.210s");fit.Audio.Write(Path.Combine(work,"real-fit.wav"));Check(StateFiles.Hash(args[0])==hash,"Original supplied voice remains unchanged");Console.WriteLine("REAL measured speed="+fit.Speed+" tail adjustment="+fit.SampleAdjustment);}
  Console.WriteLine("TOTAL ANCHORED "+count+" passed.");
 }
}
